-- Disposable fixtures. Everything is rolled back, including on failure.
\set ON_ERROR_STOP on
begin;
set local client_min_messages=notice;
create function pg_temp.expect_count(label text, query_text text, expected bigint) returns void language plpgsql as $$
declare actual bigint;
begin execute query_text into actual;
 if actual <> expected then raise exception 'FAIL %: expected %, got %', label,expected,actual; end if;
 raise notice 'PASS %',label;
end $$;
create function pg_temp.expect_error(label text, query_text text, expected_state text) returns void language plpgsql as $$
begin
 begin execute query_text;
 exception when others then
  if sqlstate <> expected_state then raise exception 'FAIL %: wanted SQLSTATE %, got % (%)',label,expected_state,sqlstate,sqlerrm; end if;
  raise notice 'PASS %',label; return;
 end;
 raise exception 'FAIL %: statement unexpectedly succeeded',label;
end $$;
